     AGENT_CODE                             opus_health_legacy_v4  2 writer(s), of which 1 UNDISCRIMINATED (1 separated by a resolved instance, 0 by redundant_of)
*/

with feeders as (
    select
        md5(upper('LNK_PARTY_ROLE|' || (LNK_PARTY_ROLE_BK__INTERMEDIARY_ID))) as LNK_PARTY_ROLE_HK
        , cast(null as varchar) as AGENT_CODE
        , INTERMEDIARY_TYPE as AGENCY_TYPE
        , IRDA_LICENSE_NO as IRDAI_AGENT_LICENCE_NUMBER
        , SPL_TDS_RATE as SPECIAL_TDS_RATE
        , STATUS as ACTIVE_INDICATOR
        , SYSTEM_DATE as APPOINTMENT_DATE
        , SUBIMD_YN as SUB_INTERMEDIARY_INDICATOR
        , LICENSE_EXPIRY_DATE as LICENCE_EXPIRY_DATE
        , LICENSE_ISSUE_DATE as LICENCE_ISSUE_DATE
        , LICENSE_TYPE as LICENCE_CATEGORY
        , 'BJAZ_INTERMEDIARY' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_intermediary') }}
    where (LNK(HUB_PARTY = nullif(trim(INTERMEDIARY_ID),''))) is not null
),

resolved as (
    select
        LNK_PARTY_ROLE_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then AGENT_CODE end) as AGENT_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then AGENCY_TYPE end) as AGENCY_TYPE,
        max(case when SOURCE_RUN = 'opus_health_v2' then IRDAI_AGENT_LICENCE_NUMBER end) as IRDAI_AGENT_LICENCE_NUMBER,
        max(case when SOURCE_RUN = 'opus_health_v2' then SPECIAL_TDS_RATE end) as SPECIAL_TDS_RATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then ACTIVE_INDICATOR end) as ACTIVE_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then APPOINTMENT_DATE end) as APPOINTMENT_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then SUB_INTERMEDIARY_INDICATOR end) as SUB_INTERMEDIARY_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then LICENCE_EXPIRY_DATE end) as LICENCE_EXPIRY_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then LICENCE_ISSUE_DATE end) as LICENCE_ISSUE_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then LICENCE_CATEGORY end) as LICENCE_CATEGORY,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by LNK_PARTY_ROLE_HK
),

hashed as (
    select
        *,
        case when AGENT_CODE is not null or AGENCY_TYPE is not null or IRDAI_AGENT_LICENCE_NUMBER is not null or SPECIAL_TDS_RATE is not null or ACTIVE_INDICATOR is not null or APPOINTMENT_DATE is not null or SUB_INTERMEDIARY_INDICATOR is not null or LICENCE_EXPIRY_DATE is not null or LICENCE_ISSUE_DATE is not null or LICENCE_CATEGORY is not null
                     then md5(upper(coalesce(cast(AGENT_CODE as varchar), '') || '|' || coalesce(cast(AGENCY_TYPE as varchar), '') || '|' || coalesce(cast(IRDAI_AGENT_LICENCE_NUMBER as varchar), '') || '|' || coalesce(cast(SPECIAL_TDS_RATE as varchar), '') || '|' || coalesce(cast(ACTIVE_INDICATOR as varchar), '') || '|' || coalesce(cast(APPOINTMENT_DATE as varchar), '') || '|' || coalesce(cast(SUB_INTERMEDIARY_INDICATOR as varchar), '') || '|' || coalesce(cast(LICENCE_EXPIRY_DATE as varchar), '') || '|' || coalesce(cast(LICENCE_ISSUE_DATE as varchar), '') || '|' || coalesce(cast(LICENCE_CATEGORY as varchar), '')))
                end as SAT_LNK_ROLE_AGENT_HASHDIFF
    from resolved
)

select * from hashed
where LNK_PARTY_ROLE_HK is not null
  and SAT_LNK_ROLE_AGENT_HASHDIFF is not null
